"""Generates the Unreal-migration documentation set from the verified content inventory + recorded state.
Statuses are deliberately conservative: only things actually verified in the Unreal project are marked beyond 'Not started'."""
import json, os
D = 'docs/unreal/'; inv = json.load(open(D + 'content_inventory.json'))
DATE = '2026-11-04'
UE = 'Unreal Engine 5.8.4 (Release-5.8), project C:/Users/decca/OneDrive/Documents/Unreal Projects/Steelandblood (Blueprint-only)'
STAT = ['Not started', 'In progress', 'Needs revision', 'Exported', 'Imported', 'Integrated', 'Tested', 'Verified complete']
COLS = ['Name', 'Source (kit module)', 'Export', 'Mesh', 'UV', 'Material', 'Rig', 'Weights', 'Animation', 'UE import', 'Integration', 'Visual check', 'Testing']

def table(rows):
    out = '| ' + ' | '.join(COLS) + ' |\n|' + '---|'*len(COLS) + '\n'
    for r in rows: out += '| ' + ' | '.join(r) + ' |\n'
    return out

def w(name, body):
    open(D + name, 'w').write('# ' + name[:-3].replace('_', ' ').title() + '\n\n_Last updated ' + DATE + '. Generated by tools/gen_docs.py from the real project state._\n\n' + body)

NS = 'Not started'
DONE_W = {'Steel Longsword': 'SM_Wpn_Longsword', 'War Hammer': 'SM_Wpn_WarHammer', 'Battle Axe': 'SM_Wpn_BattleAxe', 'Halberd': 'SM_Wpn_Halberd', 'Flanged Mace': 'SM_Wpn_FlangedMace'}

# ---- weapons
rows = []
for x in inv['weapons']:
    sm = DONE_W.get(x['name'])
    if sm: rows.append([x['name'], 'sb_props.py:' + sm, 'glTF', 'Imported', 'Imported (arc-length)', 'Integrated (MI library)', 'n/a', 'n/a', 'n/a', 'Imported', NS if sm != 'SM_Wpn_Longsword' else 'In progress (hand attach)', 'In progress', NS])
    else: rows.append([x['name']] + [NS]*12)
