  ['SK_HeroKnight v16 (armour rebuild on user model)', 'Pictures/SteelAndBlood_Knight_v16.blend + sb_v16_armor.py', 'glTF (skinned, ~174k tris)', 'Verified (Blender turnarounds)', 'Existing', 'Done in Blender (ivory/gold/crimson PBR); UE: MI library, texture bake in progress', 'Imported (same 22-bone rig)', 'Imported (rigid plates + smooth cape/tabard)', 'Imported (7 clips)', 'Imported + playable; NOTE v14-v16 clips were exported in REST pose until commit 7314ebc (fixed, PIE re-verified with visible walk/attack/block)', 'Done', 'In progress', NS],
  ['Order variants (helms)', 'sb_v16_variants.py + sb_ue_order.py: greathelm/bascinet/sallet/hooded + haute-pieces (hood rebuilt)', 'glTF per variant (155-185k tris)', 'Rendered + in-level', 'Existing', 'Bascinet, Sallet, Hooded in UE with M_SB_Armor', 'Same rig (own skeleton asset per import)', 'Same weights', 'Same 7 clips', 'Bascinet (Idle_Ready), Sallet (Idle_Guard), Hooded (Idle_AtEase), Vigil (kneeling) placed in L_RuinedCastle_Showcase, animating in PIE', 'Not started (NPC AI)', 'In progress', NS],
